'use strict';
const concepts={campus:{name:'Кампус / Ясный ритм',eyebrow:'Свои люди. Нужные навыки.',title:'Найди своего<br><span>исполнителя.</span>',copy:'От учёбы до творчества — нужная помощь рядом.'},editorial:{name:'Студенческий редактор',eyebrow:'Знания, которыми делятся',title:'Найди своего<br><span>исполнителя.</span>',copy:'От учёбы до творчества — нужная помощь рядом.'},orbit:{name:'Орбита / Спокойная глубина',eyebrow:'Твоя задача. Твоя команда.',title:'Найди своего<br><span>исполнителя.</span>',copy:'От учёбы до творчества — нужная помощь рядом.'}};
const concept=document.body.dataset.concept||'campus',meta=concepts[concept];
const icons={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/>',heart:'<path d="M20.8 4.8a5.5 5.5 0 0 0-7.8 0L12 5.9l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.4a5.5 5.5 0 0 0 0-7.8Z"/>',home:'<path d="m3 10 9-7 9 7v10H15v-6H9v6H3Z"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-10a9 9 0 0 1 19-.5Z"/><path d="M7 10h10M7 14h6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',filter:'<path d="M4 6h16M4 12h16M4 18h16"/><path d="M8 3v6M16 9v6M10 15v6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',moon:'<path d="M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3Z"/><path d="M12 6v16"/>',pen:'<path d="m4 17-1 4 4-1L20 7l-4-4Z"/><path d="m13 6 4 4"/>',code:'<path d="m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18"/>',video:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m10 9 5 3-5 3Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const brand=`<svg class="brand-mark" viewBox="0 0 112 160" aria-hidden="true"><path d="M75 5C83 1 92 4 97 11C103 20 100 30 92 35L52 60L79 66C92 69 101 76 101 86C101 93 97 98 90 102L38 136C28 143 17 139 12 131C7 122 10 112 19 106L55 83L28 79C15 77 7 69 7 60C7 53 11 48 18 44L75 5Z" fill-rule="evenodd"/></svg>`;
const services=[{id:1,kind:'math',category:'study',label:'Математика',cover:'Сложное станет понятным',symbol:'∑',title:'Разобраться с высшей математикой',description:'Пределы, интегралы и задачи — спокойно, шаг за шагом.',name:'Алина К.',specialty:'Математика · 3 курс',initials:'АК',price:900,unit:'60 мин',days:1},{id:2,kind:'design',category:'design',label:'Дизайн',cover:'Идеи, которые видят',symbol:'Aa',title:'Собрать выразительную презентацию',description:'Чёткая структура и слайды, которые поддержат твою идею.',name:'Марк С.',specialty:'Коммуникационный дизайн',initials:'МС',price:1500,unit:'проект',days:2},{id:3,kind:'code',category:'code',label:'Программирование',cover:'От вопроса к решению',symbol:'{ }',title:'Разобраться с кодом на Python',description:'Объясню логику, найду ошибку и помогу понять решение.',name:'Артём М.',specialty:'Разработка · 4 курс',initials:'АМ',price:1200,unit:'60 мин',days:1},{id:4,kind:'english',category:'study',label:'Английский',cover:'Слова становятся своими',symbol:'Hello.',title:'Практиковать разговорный английский',description:'Больше уверенности в диалогах, выступлениях и учёбе.',name:'София Л.',specialty:'Лингвистика · 3 курс',initials:'СЛ',price:800,unit:'45 мин',days:1},{id:5,kind:'video',category:'media',label:'Медиа',cover:'Истории в движении',symbol:'▶',title:'Смонтировать короткое видео',description:'Монтаж, титры и звук для проекта или студенческого события.',name:'Даниил Р.',specialty:'Видеомонтаж и моушн',initials:'ДР',price:1800,unit:'ролик',days:3},{id:6,kind:'career',category:'study',label:'Карьера',cover:'Твой следующий шаг',symbol:'→',title:'Подготовить резюме для стажировки',description:'Выделим сильные стороны и понятно расскажем об опыте.',name:'Ирина П.',specialty:'Карьерное консультирование',initials:'ИП',price:700,unit:'разбор',days:2}];
const categories=[['all','grid','Все услуги'],['study','book','Учёба'],['design','pen','Дизайн'],['code','code','Код'],['media','video','Медиа']];
const nav=[['home','Главная'],['search','Поиск'],['heart','Избранное'],['chat','Чаты'],['user','Профиль']];
const state={query:'',category:'all',maxPrice:'',deadline:'any',sort:'relevant',favorites:new Set([2]),onlyFavorites:false};
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=(suffix)=>`<div class="filter-group"><label for="max-${suffix}">Бюджет до</label><input id="max-${suffix}" name="maxPrice" type="number" min="0" step="100" inputmode="numeric" placeholder="Любая сумма, ₽"><span class="field-hint">Цена предложения без дополнительных услуг</span></div><div class="filter-group"><label for="days-${suffix}">Когда нужна помощь</label><select id="days-${suffix}" name="deadline"><option value="any">В любой срок</option><option value="1">В течение дня</option><option value="2">До 2 дней</option><option value="3">До 3 дней</option></select></div><label class="filter-check"><input name="onlyFavorites" type="checkbox">Только избранное</label>`;
document.querySelector('#app').innerHTML=`<div class="app"><header class="topbar"><a class="brand" href="#search-title" aria-label="STUDLY — к поиску">${brand}<span>STUDLY</span></a><nav class="desktop-nav" aria-label="Основная навигация">${nav.slice(0,4).map(([key,label])=>`<button type="button" class="nav-item ${key==='search'?'is-active':''}" data-nav="${key}" ${key==='search'?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="header-actions"><span class="demo-label">ДЕМО</span><button type="button" class="publish-btn">Предложить услугу</button><button type="button" class="icon-btn theme-toggle" aria-label="Переключить светлую и тёмную тему">${icon('moon')}</button></div></header><main class="workspace"><section class="intro" aria-labelledby="search-title"><p class="eyebrow">${meta.eyebrow}</p><h1 class="intro-title" id="search-title">${meta.title}</h1><p class="intro-copy">${meta.copy}</p><div class="intro-art" aria-hidden="true"></div></section><form class="search-form" role="search">${icon('search')}<label class="sr-only" for="search">Поиск услуг и исполнителей</label><input class="search-input" id="search" type="search" placeholder="Что тебе нужно?" autocomplete="off"><button type="button" class="icon-btn clear-search" aria-label="Очистить поиск" hidden>${icon('close')}</button><button type="submit" class="search-submit" aria-label="Найти услуги"><span class="button-label">Найти</span>${icon('arrow')}</button></form><nav class="category-list" aria-label="Категории услуг">${categories.map(([key,i,label])=>`<button type="button" class="category-chip" data-category="${key}" aria-pressed="${key==='all'}">${icon(i)}${label}</button>`).join('')}</nav><div class="catalog-layout"><aside class="filters-panel" aria-label="Фильтры"><div class="filter-head">Фильтры<button type="button" class="reset-btn">Сбросить</button></div>${fields('desktop')}<p class="filter-note">Демонстрационные предложения.<br>Все имена и данные вымышлены.</p></aside><section class="results" aria-labelledby="results-title"><div class="results-toolbar"><div><h2 class="results-title" id="results-title">Услуги</h2><span class="results-count" aria-live="polite"></span></div><div class="toolbar-actions"><button type="button" class="filter-toggle">${icon('filter')}<span class="button-label">Фильтры</span><span class="sr-only">Открыть фильтры</span></button><label class="sr-only" for="sort">Сортировка</label><select class="sort-select" id="sort"><option value="relevant">По умолчанию</option><option value="priceAsc">Сначала дешевле</option><option value="priceDesc">Сначала дороже</option><option value="duration">Сначала быстрее</option></select></div></div><div class="active-filters"></div><div class="service-grid"></div><div class="empty-state" hidden>${icon('search')}<h3>Пока ничего не нашлось</h3><p>Попробуй другой запрос или убери часть фильтров.</p><button type="button" class="primary-btn reset-all">Сбросить поиск и фильтры</button></div></section></div><section class="components-panel" hidden><h2 class="component-heading">Карточка и состояния кнопки</h2><div class="button-states">${[['','Обычная'],['sample-hover','Наведение'],['sample-active','Нажатие'],['sample-focus','Фокус']].map(([c,t])=>`<div class="button-sample"><span>${t}</span><button type="button" class="primary-btn ${c}">Посмотреть услугу</button></div>`).join('')}<div class="button-sample"><span>Недоступна</span><button type="button" class="primary-btn" disabled>Оформить заказ</button></div></div><div class="card-specimen"></div></section></main><nav class="bottom-nav" aria-label="Нижняя навигация">${nav.map(([key,label])=>`<button type="button" class="bottom-item ${key==='search'?'is-active':''}" data-nav="${key}" ${key==='search'?'aria-current="page"':''}>${icon(key)}<span>${label}</span></button>`).join('')}</nav><dialog class="filter-dialog" aria-labelledby="filter-title"><form class="filter-form" method="dialog"><div class="dialog-heading"><h2 id="filter-title">Фильтры</h2><button type="button" class="icon-btn close-filters" aria-label="Закрыть фильтры">${icon('close')}</button></div>${fields('mobile')}<div class="dialog-actions"><button type="button" class="secondary-btn reset-mobile">Сбросить</button><button type="submit" class="primary-btn">Показать услуги</button></div></form></dialog><dialog class="detail-dialog" aria-labelledby="detail-title"><div class="dialog-inner"></div></dialog><div class="toast" role="status"></div></div>`;
const card=s=>`<article class="service-card" data-kind="${s.kind}"><div class="service-cover"><span class="cover-label">${s.cover}</span><span class="cover-symbol" aria-hidden="true">${s.symbol}</span><button type="button" class="favorite-btn" data-favorite="${s.id}" aria-label="${state.favorites.has(s.id)?'Убрать из избранного':'Добавить в избранное'}: ${s.title}" aria-pressed="${state.favorites.has(s.id)}">${icon('heart')}</button></div><div class="card-body"><span class="card-category">${s.label}</span><h3 class="service-title">${s.title}</h3><p class="service-description">${s.description}</p><div class="performer"><span class="avatar" aria-hidden="true">${s.initials}</span><span class="performer-copy"><strong class="performer-name">${s.name}</strong><span class="performer-specialty">${s.specialty}</span></span></div><div class="card-bottom"><span class="price-block"><strong class="price">${money(s.price)}</strong><span class="price-unit">/ ${s.unit}</span></span><span class="delivery">${icon('clock')}${s.days===1?'От 1 дня':`До ${s.days} дней`}</span></div><button type="button" class="detail-btn" data-detail="${s.id}">Посмотреть услугу</button></div></article>`;
let toastTimer;
function toast(text){const el=document.querySelector('.toast');el.textContent=text;el.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('is-visible'),2800);}
function render(){let list=services.filter(s=>(state.category==='all'||s.category===state.category)&&(!state.maxPrice||s.price<=Number(state.maxPrice))&&(state.deadline==='any'||s.days<=Number(state.deadline))&&(!state.onlyFavorites||state.favorites.has(s.id))&&(`${s.title} ${s.description} ${s.name} ${s.label}`.toLowerCase().includes(state.query.toLowerCase().trim())));if(state.sort==='priceAsc')list.sort((a,b)=>a.price-b.price);if(state.sort==='priceDesc')list.sort((a,b)=>b.price-a.price);if(state.sort==='duration')list.sort((a,b)=>a.days-b.days);document.querySelector('.service-grid').innerHTML=list.map(card).join('');document.querySelector('.results-count').textContent=String(list.length);document.querySelector('.empty-state').hidden=list.length>0;document.querySelector('.clear-search').hidden=!state.query;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===state.category)));const tags=[];if(state.maxPrice)tags.push(`До ${money(Number(state.maxPrice))}`);if(state.deadline!=='any')tags.push(`Срок: до ${state.deadline} дн.`);if(state.onlyFavorites)tags.push('Избранное');document.querySelector('.active-filters').innerHTML=tags.map(t=>`<span class="filter-tag">${escapeHTML(t)}</span>`).join('');}
function resetFilters(){state.maxPrice='';state.deadline='any';state.onlyFavorites=false;document.querySelectorAll('[name=maxPrice]').forEach(x=>x.value='');document.querySelectorAll('[name=deadline]').forEach(x=>x.value='any');document.querySelectorAll('[name=onlyFavorites]').forEach(x=>x.checked=false);render();}
document.querySelector('.search-form').addEventListener('submit',e=>{e.preventDefault();state.query=document.querySelector('#search').value;render();});
document.querySelector('#search').addEventListener('input',e=>{state.query=e.target.value;render();});
document.querySelector('.clear-search').addEventListener('click',()=>{state.query='';document.querySelector('#search').value='';render();document.querySelector('#search').focus();});
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;render();}));
document.querySelector('#sort').addEventListener('change',e=>{state.sort=e.target.value;render();});
document.querySelectorAll('.filters-panel [name]').forEach(f=>f.addEventListener('change',()=>{if(f.name==='maxPrice'&&!f.checkValidity()){f.reportValidity();return;}state[f.name]=f.type==='checkbox'?f.checked:f.value;render();}));
document.querySelector('.reset-btn').addEventListener('click',resetFilters);
document.querySelector('.reset-all').addEventListener('click',()=>{state.query='';state.category='all';document.querySelector('#search').value='';resetFilters();});
const filters=document.querySelector('.filter-dialog');
document.querySelector('.filter-toggle').addEventListener('click',()=>{filters.querySelector('[name=maxPrice]').value=state.maxPrice;filters.querySelector('[name=deadline]').value=state.deadline;filters.querySelector('[name=onlyFavorites]').checked=state.onlyFavorites;filters.showModal();});
document.querySelector('.close-filters').addEventListener('click',()=>filters.close());
document.querySelector('.filter-form').addEventListener('submit',e=>{e.preventDefault();const max=filters.querySelector('[name=maxPrice]');if(!max.checkValidity()){max.reportValidity();return;}state.maxPrice=max.value;state.deadline=filters.querySelector('[name=deadline]').value;state.onlyFavorites=filters.querySelector('[name=onlyFavorites]').checked;document.querySelector('#max-desktop').value=state.maxPrice;document.querySelector('#days-desktop').value=state.deadline;document.querySelector('.filters-panel [name=onlyFavorites]').checked=state.onlyFavorites;render();filters.close();});
document.querySelector('.reset-mobile').addEventListener('click',()=>{filters.querySelector('[name=maxPrice]').value='';filters.querySelector('[name=deadline]').value='any';filters.querySelector('[name=onlyFavorites]').checked=false;});
document.addEventListener('click',e=>{const favorite=e.target.closest('[data-favorite]');if(favorite){const id=Number(favorite.dataset.favorite);const focusKey=id;state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);render();document.querySelector(`[data-favorite="${focusKey}"]`)?.focus({preventScroll:true});toast(state.favorites.has(id)?'Добавлено в избранное':'Удалено из избранного');}const detail=e.target.closest('[data-detail]');if(detail){const s=services.find(s=>s.id===Number(detail.dataset.detail));document.querySelector('.detail-dialog .dialog-inner').innerHTML=`<div class="dialog-heading"><h2 id="detail-title">${s.title}</h2><button type="button" class="icon-btn close-detail" aria-label="Закрыть карточку">${icon('close')}</button></div><span class="demo-label">ДЕМОНСТРАЦИОННАЯ УСЛУГА</span><p>${s.description}</p><div class="performer"><span class="avatar">${s.initials}</span><span class="performer-copy"><strong>${s.name}</strong><span class="performer-specialty">${s.specialty}</span></span></div><strong class="detail-price">${money(s.price)}</strong><span>За ${s.unit} · ${s.days===1?'от 1 дня':`до ${s.days} дней`}</span><p>Включено: обсуждение задачи и работа по описанному объёму. Все данные вымышлены. Заказы и платежи в этом прототипе недоступны.</p><div class="dialog-actions"><button type="button" class="secondary-btn close-detail">Назад к поиску</button><button type="button" class="primary-btn" disabled>Оформить заказ</button></div>`;document.querySelector('.detail-dialog').showModal();}if(e.target.closest('.close-detail'))document.querySelector('.detail-dialog').close();});
document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.nav==='search'){document.querySelector('#search').focus();return;}toast(`«${b.textContent.trim()}» — пример навигации. Сейчас открыт поиск.`);}));
document.querySelector('.publish-btn').addEventListener('click',()=>toast('Это визуальный прототип. Публикация услуг недоступна.'));
const params=new URLSearchParams(location.search);let theme=document.body.dataset.previewTheme||params.get('theme')||'auto';const media=matchMedia('(prefers-color-scheme: dark)');
function setTheme(value){theme=value;const dark=value==='dark'||(value==='auto'&&media.matches);document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('.theme-toggle').innerHTML=icon(dark?'sun':'moon');document.querySelector('.theme-toggle').setAttribute('aria-label',dark?'Включить светлую тему':'Включить тёмную тему');}
document.querySelector('.theme-toggle').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));media.addEventListener('change',()=>{if(theme==='auto')setTheme('auto');});
if(params.get('components')==='1'||document.body.dataset.components==='1'){document.body.classList.add('component-view');document.querySelector('.components-panel').hidden=false;document.querySelector('.card-specimen').innerHTML=card(services[0]);}
if(params.get('safe')==='1'){document.documentElement.classList.add('simulate-safe-area');}
document.title=`STUDLY — ${meta.name}`;setTheme(theme);render();
